import React, { useState } from 'react';
import { MapPin, Clock, Phone, Plus, Trash2, CheckCircle2, AlertCircle, Share2, Heart } from 'lucide-react';

export default function FeedPage() {
  const [posts, setPosts] = useState([
    {
      id: 1,
      name: "আরিফুল ইসলাম",
      avatar: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?w=150",
      bloodGroup: "O+",
      bagsNeeded: 2,
      hospital: "ঢাকা মেডিকেল কলেজ হাসপাতাল",
      location: "শাহবাগ, ঢাকা",
      phone: "01711223344",
      time: "১০ মিনিট আগে",
      urgency: "জরুরি",
      details: "আমার রোগীর জন্য জরুরি ভিত্তিতে ২ ব্যাগ O+ রক্তের প্রয়োজন। অপারেশন দুপুর ২টায়।",
      isMyPost: true,
      status: "Active"
    },
    {
      id: 2,
      name: "সামিয়া রহমান",
      avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=150",
      bloodGroup: "AB-",
      bagsNeeded: 1,
      hospital: "স্কয়ার হাসপাতাল",
      location: "পান্থপথ, ঢাকা",
      phone: "01899887766",
      time: "১ ঘণ্টা আগে",
      urgency: "খুব জরুরি",
      details: "ডেঙ্গু রোগীর প্লাটিলেটের জন্য AB- রক্তদাতা প্রয়োজন। দয়া করে দ্রুত যোগাযোগ করুন।",
      isMyPost: false,
      status: "Active"
    }
  ]);

  const [showModal, setShowModal] = useState(false);
  const [newPost, setNewPost] = useState({
    bloodGroup: 'O+',
    bagsNeeded: 1,
    hospital: '',
    location: '',
    phone: '',
    details: ''
  });

  // পোস্ট ডিলিট করার হ্যান্ডলার
  const handleDelete = (id) => {
    if (window.confirm("আপনি কি নিশ্চিত যে পোস্টটি ডিলিট করতে চান?")) {
      setPosts(posts.filter(p => p.id !== id));
    }
  };

  // রক্ত পাওয়া হয়ে গেলে সম্পন্ন করার হ্যান্ডলার
  const handleResolve = (id) => {
    setPosts(posts.map(p => p.id === id ? { ...p, status: 'Resolved' } : p));
  };

  // নতুন পোস্ট সাবমিট হ্যান্ডলার
  const handleCreatePost = (e) => {
    e.preventDefault();
    const created = {
      id: Date.now(),
      name: "আপনার নাম (বর্তমান ইউজার)",
      avatar: "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=150",
      ...newPost,
      time: "এখনই",
      urgency: "জরুরি",
      isMyPost: true,
      status: "Active"
    };
    setPosts([created, ...posts]);
    setShowModal(false);
    setNewPost({ bloodGroup: 'O+', bagsNeeded: 1, hospital: '', location: '', phone: '', details: '' });
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-6 space-y-6">
      
      {/* Top Banner & Post Create Trigger */}
      <div className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-full bg-rose-100 text-brand-600 font-bold flex items-center justify-center">
            🩸
          </div>
          <div>
            <h1 className="text-base font-black text-slate-900">ইমার্জেন্সি ব্লাড ফিড</h1>
            <p className="text-xs text-slate-500 font-medium">জরুরি রক্তের প্রয়োজনে পোস্ট করুন</p>
          </div>
        </div>

        <button 
          onClick={() => setShowModal(true)}
          className="bg-brand-600 hover:bg-brand-700 text-white px-4 py-2.5 rounded-full text-xs font-bold flex items-center gap-1.5 shadow-md shadow-brand-600/30 transition active:scale-95"
        >
          <Plus className="w-4 h-4" /> পোস্ট করুন
        </button>
      </div>

      {/* Feed List */}
      <div className="space-y-4">
        {posts.map((post) => (
          <div 
            key={post.id} 
            className={`bg-white rounded-3xl p-5 border shadow-sm transition space-y-4 ${
              post.status === 'Resolved' ? 'opacity-60 border-slate-200 bg-slate-50' : 'border-rose-100'
            }`}
          >
            {/* Header */}
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <img src={post.avatar} alt={post.name} className="w-10 h-10 rounded-full object-cover border border-slate-200" />
                <div>
                  <h3 className="text-sm font-bold text-slate-900 flex items-center gap-2">
                    {post.name}
                    {post.isMyPost && <span className="bg-slate-100 text-slate-600 text-[10px] px-2 py-0.5 rounded-full">আপনার পোস্ট</span>}
                  </h3>
                  <div className="flex items-center gap-2 text-[11px] text-slate-400 font-medium">
                    <Clock className="w-3 h-3" /> {post.time}
                  </div>
                </div>
              </div>

              {/* Blood Badge */}
              <div className="text-right">
                <span className="bg-brand-600 text-white text-sm font-black px-3.5 py-1.5 rounded-2xl shadow-sm inline-block">
                  {post.bloodGroup}
                </span>
                <p className="text-[10px] font-bold text-slate-500 mt-1">{post.bagsNeeded} ব্যাগ প্রয়োজন</p>
              </div>
            </div>

            {/* Content Details */}
            <p className="text-xs text-slate-700 font-medium leading-relaxed bg-slate-50 p-3 rounded-2xl border border-slate-100">
              {post.details}
            </p>

            {/* Meta Info */}
            <div className="space-y-1.5 text-xs text-slate-600 font-medium">
              <div className="flex items-center gap-2">
                <MapPin className="w-4 h-4 text-brand-600" />
                <span><strong>হাসপাতাল:</strong> {post.hospital}, {post.location}</span>
              </div>
            </div>

            {/* Action Buttons */}
            <div className="pt-2 border-t border-slate-100 flex items-center justify-between gap-2">
              <a 
                href={`tel:${post.phone}`}
                className="flex-1 bg-rose-50 hover:bg-rose-100 text-brand-700 font-bold text-xs py-2.5 rounded-xl flex items-center justify-center gap-2 transition"
              >
                <Phone className="w-4 h-4" /> কল করুন ({post.phone})
              </a>

              {post.isMyPost && post.status === 'Active' && (
                <>
                  <button 
                    onClick={() => handleResolve(post.id)}
                    className="p-2.5 bg-emerald-50 text-emerald-600 hover:bg-emerald-100 rounded-xl font-bold text-xs flex items-center gap-1 transition"
                    title="রক্ত পাওয়া গেছে"
                  >
                    <CheckCircle2 className="w-4 h-4" />
                  </button>
                  <button 
                    onClick={() => handleDelete(post.id)}
                    className="p-2.5 bg-rose-50 text-rose-600 hover:bg-rose-100 rounded-xl font-bold text-xs flex items-center gap-1 transition"
                    title="ডিলিট করুন"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* --- CREATE POST MODAL --- */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-3xl p-6 shadow-2xl space-y-4">
            <h2 className="text-lg font-black text-slate-900 border-b pb-3">জরুরি রক্তের অনুরোধ পোস্ট করুন</h2>

            <form onSubmit={handleCreatePost} className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">রক্তের গ্রুপ</label>
                  <select 
                    value={newPost.bloodGroup} 
                    onChange={(e) => setNewPost({ ...newPost, bloodGroup: e.target.value })}
                    className="w-full p-2.5 border rounded-xl text-xs font-bold bg-slate-50"
                  >
                    {['A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-'].map(bg => (
                      <option key={bg} value={bg}>{bg}</option>
                    ))}
                  </select>
                </div>

                <div>
                  <label className="block text-xs font-bold text-slate-700 mb-1">কয় ব্যাগ?</label>
                  <input 
                    type="number" 
                    min="1"
                    value={newPost.bagsNeeded}
                    onChange={(e) => setNewPost({ ...newPost, bagsNeeded: e.target.value })}
                    className="w-full p-2.5 border rounded-xl text-xs font-medium bg-slate-50"
                    required
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">হাসপাতালের নাম</label>
                <input 
                  type="text" 
                  placeholder="যেমন: ঢাকা মেডিকেল" 
                  value={newPost.hospital}
                  onChange={(e) => setNewPost({ ...newPost, hospital: e.target.value })}
                  className="w-full p-2.5 border rounded-xl text-xs font-medium bg-slate-50"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">লোকেশন / এলাকা</label>
                <input 
                  type="text" 
                  placeholder="যেমন: শাহবাগ, ঢাকা" 
                  value={newPost.location}
                  onChange={(e) => setNewPost({ ...newPost, location: e.target.value })}
                  className="w-full p-2.5 border rounded-xl text-xs font-medium bg-slate-50"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">যোগাযোগের নম্বর</label>
                <input 
                  type="tel" 
                  placeholder="01700000000" 
                  value={newPost.phone}
                  onChange={(e) => setNewPost({ ...newPost, phone: e.target.value })}
                  className="w-full p-2.5 border rounded-xl text-xs font-medium bg-slate-50"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 mb-1">বিস্তারিত বিবরণ</label>
                <textarea 
                  rows="3" 
                  placeholder="রোগীর অবস্থা বা অতিরিক্ত তথ্য লিখুন..." 
                  value={newPost.details}
                  onChange={(e) => setNewPost({ ...newPost, details: e.target.value })}
                  className="w-full p-2.5 border rounded-xl text-xs font-medium bg-slate-50"
                  required
                />
              </div>

              <div className="flex items-center gap-3 pt-2">
                <button 
                  type="button" 
                  onClick={() => setShowModal(false)}
                  className="flex-1 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-xl text-xs font-bold transition"
                >
                  বাতিল
                </button>
                <button 
                  type="submit" 
                  className="flex-1 py-3 bg-brand-600 hover:bg-brand-700 text-white rounded-xl text-xs font-bold shadow-md shadow-brand-600/30 transition"
                >
                  পোস্ট প্রকাশ করুন
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
}
